import json
import time
import random
from datetime import datetime, timedelta
from confluent_kafka import Producer

producer = Producer({"bootstrap.servers": "kafka:9092", "enable.idempotence": True})

def deliver(err, msg):
    if err:
        print(f"delivery failed: {err}")

def valid_order(order_id, ts):
    return {"order_id": order_id, "amount": round(random.uniform(1, 500), 2),
            "event_time": ts.isoformat(), "currency": "USD"}

def inject(topic="orders", n=1000, poison_rate=0.02, late_rate=0.05, dup_rate=0.03):
    now = datetime.utcnow()
    stats = {"valid": 0, "poison": 0, "late": 0, "dup": 0}
    for i in range(n):
        roll = random.random()
        if roll < poison_rate:
            # Poison message: malformed / wrong schema (missing amount, bad json)
            payload = b'{"order_id": "' + str(i).encode() + b'", "amount": '
            stats["poison"] += 1
        elif roll < poison_rate + late_rate:
            # Late / out-of-order event: timestamp 2 hours in the past
            rec = valid_order(f"ord-{i}", now - timedelta(hours=2))
            payload = json.dumps(rec).encode()
            stats["late"] += 1
        else:
            rec = valid_order(f"ord-{i}", now)
            payload = json.dumps(rec).encode()
            stats["valid"] += 1
            if random.random() < dup_rate:
                # Duplicate: send the exact same record again
                producer.produce(topic, payload, callback=deliver)
                stats["dup"] += 1
        producer.produce(topic, payload, callback=deliver)
        producer.poll(0)
        time.sleep(0.001)
    producer.flush()
    print(f"injection complete: {stats}")
    return stats

if __name__ == "__main__":
    inject()
